// Tiny procedural WebAudio engine — no external audio files.
export class AudioEngine {
  constructor() {
    this.ctx = null;
    this.master = null;
    this.musicGain = null;
    this.enabled = true;
    this.musicTimer = null;
    this.step = 0;
    this.started = false;
  }

  init() {
    if (this.ctx) {
      if (this.ctx.state === 'suspended') this.ctx.resume();
      return;
    }
    const Ctx = window.AudioContext || window.webkitAudioContext;
    if (!Ctx) return;
    this.ctx = new Ctx();
    this.master = this.ctx.createGain();
    this.master.gain.value = this.enabled ? 0.55 : 0;
    const comp = this.ctx.createDynamicsCompressor();
    comp.threshold.value = -18;
    comp.knee.value = 22;
    comp.ratio.value = 5;
    this.master.connect(comp);
    comp.connect(this.ctx.destination);

    this.musicGain = this.ctx.createGain();
    this.musicGain.gain.value = 0.11;
    this.musicGain.connect(this.master);

    this.sfxGain = this.ctx.createGain();
    this.sfxGain.gain.value = 0.9;
    this.sfxGain.connect(this.master);
  }

  setEnabled(on) {
    this.enabled = on;
    if (this.master && this.ctx) {
      this.master.gain.cancelScheduledValues(this.ctx.currentTime);
      this.master.gain.setTargetAtTime(on ? 0.55 : 0, this.ctx.currentTime, 0.05);
    }
  }

  toggle() {
    this.setEnabled(!this.enabled);
    return this.enabled;
  }

  now() {
    return this.ctx ? this.ctx.currentTime : 0;
  }

  tone({ freq = 440, dur = 0.12, type = 'sine', gain = 0.15, slide = null, delay = 0, dest = null }) {
    if (!this.ctx || !this.enabled) return;
    const t0 = this.ctx.currentTime + delay;
    const o = this.ctx.createOscillator();
    const g = this.ctx.createGain();
    o.type = type;
    o.frequency.setValueAtTime(freq, t0);
    if (slide != null) o.frequency.exponentialRampToValueAtTime(Math.max(30, slide), t0 + dur);
    g.gain.setValueAtTime(0.0001, t0);
    g.gain.exponentialRampToValueAtTime(gain, t0 + 0.008);
    g.gain.exponentialRampToValueAtTime(0.0001, t0 + dur);
    o.connect(g);
    g.connect(dest || this.sfxGain);
    o.start(t0);
    o.stop(t0 + dur + 0.03);
  }

  noise({ dur = 0.18, gain = 0.18, freq = 1200, type = 'lowpass', delay = 0, dest = null }) {
    if (!this.ctx || !this.enabled) return;
    const t0 = this.ctx.currentTime + delay;
    const len = Math.max(1, Math.floor(this.ctx.sampleRate * dur));
    const buf = this.ctx.createBuffer(1, len, this.ctx.sampleRate);
    const data = buf.getChannelData(0);
    for (let i = 0; i < len; i++) data[i] = Math.random() * 2 - 1;
    const src = this.ctx.createBufferSource();
    src.buffer = buf;
    const filter = this.ctx.createBiquadFilter();
    filter.type = type;
    filter.frequency.value = freq;
    const g = this.ctx.createGain();
    g.gain.setValueAtTime(gain, t0);
    g.gain.exponentialRampToValueAtTime(0.0001, t0 + dur);
    src.connect(filter);
    filter.connect(g);
    g.connect(dest || this.sfxGain);
    src.start(t0);
  }

  click() {
    this.tone({ freq: 620, dur: 0.055, type: 'square', gain: 0.06 });
    this.tone({ freq: 940, dur: 0.04, type: 'square', gain: 0.035, delay: 0.035 });
  }

  card() {
    this.noise({ dur: 0.22, gain: 0.09, freq: 2200, type: 'highpass' });
    this.tone({ freq: 320, slide: 720, dur: 0.18, type: 'triangle', gain: 0.06 });
  }

  tick() {
    this.tone({ freq: 1100, dur: 0.03, type: 'square', gain: 0.035 });
  }

  countdown(final = false) {
    this.tone({ freq: final ? 880 : 440, dur: 0.12, type: 'square', gain: 0.08 });
  }

  success(perfect = false) {
    const notes = perfect ? [523, 659, 784, 1047, 1319] : [523, 659, 784];
    notes.forEach((f, i) => {
      this.tone({ freq: f, dur: 0.2, type: 'triangle', gain: 0.13, delay: i * 0.075 });
      this.tone({ freq: f * 2, dur: 0.12, type: 'sine', gain: 0.045, delay: i * 0.075 });
    });
    if (perfect) this.noise({ dur: 0.5, gain: 0.05, freq: 6000, type: 'highpass', delay: 0.2 });
  }

  fail() {
    this.tone({ freq: 240, slide: 90, dur: 0.4, type: 'sawtooth', gain: 0.09 });
    this.tone({ freq: 170, slide: 60, dur: 0.45, type: 'square', gain: 0.06, delay: 0.04 });
  }

  slap() {
    this.noise({ dur: 0.09, gain: 0.5, freq: 1800, type: 'bandpass' });
    this.tone({ freq: 140, slide: 45, dur: 0.22, type: 'sine', gain: 0.42 });
    this.noise({ dur: 0.18, gain: 0.16, freq: 500, type: 'lowpass', delay: 0.02 });
  }

  whoosh() {
    this.noise({ dur: 0.22, gain: 0.08, freq: 900, type: 'bandpass' });
  }

  roundStart() {
    [392, 523, 659].forEach((f, i) =>
      this.tone({ freq: f, dur: 0.18, type: 'square', gain: 0.07, delay: i * 0.09 })
    );
    this.noise({ dur: 0.35, gain: 0.07, freq: 400, type: 'lowpass' });
  }

  startMusic() {
    if (this.musicTimer || !this.ctx) return;
    this.started = true;
    const bass = [55, 55, 65.4, 73.4, 55, 82.4, 73.4, 65.4];
    const chords = [
      [220, 261.6, 329.6],
      [196, 246.9, 293.7],
      [174.6, 220, 261.6],
      [196, 246.9, 329.6]
    ];
    const stepMs = 280;
    this.musicTimer = setInterval(() => {
      if (!this.ctx || !this.enabled || this.ctx.state !== 'running') return;
      const s = this.step % 16;
      if (s % 4 === 0) {
        this.tone({ freq: 110, slide: 42, dur: 0.16, type: 'sine', gain: 0.2, dest: this.musicGain });
      }
      if (s % 2 === 0) {
        this.tone({ freq: bass[(s / 2) % bass.length], dur: 0.22, type: 'triangle', gain: 0.075, dest: this.musicGain });
      }
      if (s === 0 || s === 6 || s === 10) {
        const c = chords[Math.floor(this.step / 16) % chords.length];
        c.forEach((f) => this.tone({ freq: f, dur: 0.13, type: 'square', gain: 0.022, dest: this.musicGain }));
      }
      if (s % 2 === 1) {
        this.noise({ dur: 0.035, gain: 0.025, freq: 7000, type: 'highpass', dest: this.musicGain });
      }
      if (s === 4 || s === 12) {
        this.noise({ dur: 0.09, gain: 0.06, freq: 1400, type: 'bandpass', dest: this.musicGain });
      }
      this.step++;
    }, stepMs);
  }

  stopMusic() {
    if (this.musicTimer) clearInterval(this.musicTimer);
    this.musicTimer = null;
  }
}

import * as THREE from '../vendor/three.module.min.js';
import { SIBLINGS, DAD_SUCCESS } from './data.js';

const TAU = Math.PI * 2;
const clamp01 = (v) => Math.max(0, Math.min(1, v));
const easeInOut = (t) => (t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2);
const wait = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

function makeCanvasTexture(w, h, draw, repeat = null) {
  const c = document.createElement('canvas');
  c.width = w;
  c.height = h;
  const ctx = c.getContext('2d');
  draw(ctx, w, h);
  const tex = new THREE.CanvasTexture(c);
  tex.colorSpace = THREE.SRGBColorSpace;
  tex.anisotropy = 4;
  if (repeat) {
    tex.wrapS = tex.wrapT = THREE.RepeatWrapping;
    tex.repeat.set(repeat[0], repeat[1]);
  }
  return tex;
}

function std(color, extra = {}) {
  return new THREE.MeshStandardMaterial({ color, roughness: 0.78, metalness: 0.02, ...extra });
}

function addBox(parent, w, h, d, x, y, z, material, extra = {}) {
  const mesh = new THREE.Mesh(new THREE.BoxGeometry(w, h, d), material);
  mesh.position.set(x, y, z);
  Object.assign(mesh, extra);
  parent.add(mesh);
  return mesh;
}

function addCyl(parent, rt, rb, h, x, y, z, material, seg = 12) {
  const mesh = new THREE.Mesh(new THREE.CylinderGeometry(rt, rb, h, seg), material);
  mesh.position.set(x, y, z);
  parent.add(mesh);
  return mesh;
}

function addSphere(parent, r, x, y, z, material, seg = 12) {
  const mesh = new THREE.Mesh(new THREE.SphereGeometry(r, seg, Math.max(6, seg - 2)), material);
  mesh.position.set(x, y, z);
  parent.add(mesh);
  return mesh;
}

export function createWorld(canvas) {
  const renderer = new THREE.WebGLRenderer({
    canvas,
    antialias: true,
    powerPreference: 'high-performance',
    alpha: false
  });
  renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
  renderer.outputColorSpace = THREE.SRGBColorSpace;
  renderer.toneMapping = THREE.ACESFilmicToneMapping;
  renderer.toneMappingExposure = 1.06;
  renderer.shadowMap.enabled = true;
  renderer.shadowMap.type = THREE.PCFSoftShadowMap;

  const scene = new THREE.Scene();
  scene.background = new THREE.Color(0x140b1e);
  scene.fog = new THREE.Fog(0x1b0f28, 13, 27);

  const camera = new THREE.PerspectiveCamera(46, 1, 0.1, 80);
  const camTarget = new THREE.Vector3(0, 1.05, -1.3);
  let camTween = null;
  let mode = 'all';
  let activeId = null;
  let shake = 0;
  let time = 0;
  let layoutMode = '';
  let trophy = null;
  let trophyHost = null;
  let effectBurstTimer = 0;

  const effects = [];
  const characters = {};
  const homes = {};
  const PORTRAIT_SLOTS = [
    { x: -1.42, z: -1.72 },
    { x: -0.48, z: -0.96 },
    { x: 0.48, z: -0.96 },
    { x: 1.42, z: -1.72 }
  ];
  const LANDSCAPE_SLOTS = [
    { x: -2.2, z: -1.5 },
    { x: -0.74, z: -1.14 },
    { x: 0.74, z: -1.14 },
    { x: 2.2, z: -1.5 }
  ];

  // ---------------------------------------------------------------- textures
  const wallpaperTex = makeCanvasTexture(
    256,
    256,
    (ctx, w, h) => {
      ctx.fillStyle = '#d7b98f';
      ctx.fillRect(0, 0, w, h);
      for (let x = 0; x < w; x += 32) {
        ctx.fillStyle = x % 64 === 0 ? '#cba978' : '#d2b286';
        ctx.fillRect(x + 6, 0, 13, h);
        ctx.fillStyle = '#b58e63';
        ctx.fillRect(x + 6, 0, 2, h);
        ctx.fillRect(x + 17, 0, 1, h);
      }
      ctx.globalAlpha = 0.5;
      for (let y = 18; y < h; y += 42) {
        for (let x = 20; x < w; x += 64) {
          ctx.fillStyle = '#a97a66';
          ctx.beginPath();
          ctx.moveTo(x, y - 5);
          ctx.lineTo(x + 5, y);
          ctx.lineTo(x, y + 5);
          ctx.lineTo(x - 5, y);
          ctx.closePath();
          ctx.fill();
        }
      }
      ctx.globalAlpha = 1;
    },
    [4, 2]
  );

  const carpetTex = makeCanvasTexture(
    256,
    256,
    (ctx, w, h) => {
      ctx.fillStyle = '#1e6c63';
      ctx.fillRect(0, 0, w, h);
      ctx.strokeStyle = '#2b8d80';
      ctx.lineWidth = 2;
      for (let y = 0; y < h; y += 32) {
        ctx.beginPath();
        ctx.moveTo(0, y);
        ctx.bezierCurveTo(w * 0.25, y + 14, w * 0.5, y - 14, w, y);
        ctx.stroke();
      }
      for (let y = 16; y < h; y += 64) {
        for (let x = 16; x < w; x += 64) {
          ctx.fillStyle = 'rgba(255,210,63,.18)';
          ctx.beginPath();
          ctx.arc(x, y, 6, 0, TAU);
          ctx.fill();
          ctx.fillStyle = 'rgba(255,47,135,.14)';
          ctx.fillRect(x + 22, y - 4, 20, 3);
        }
      }
    },
    [5, 5]
  );

  const rugTex = makeCanvasTexture(512, 512, (ctx, w, h) => {
    ctx.fillStyle = '#51254e';
    ctx.fillRect(0, 0, w, h);
    ctx.strokeStyle = '#ffd23f';
    ctx.lineWidth = 11;
    ctx.strokeRect(15, 15, w - 30, h - 30);
    ctx.strokeStyle = '#ff2f87';
    ctx.lineWidth = 5;
    ctx.strokeRect(30, 30, w - 60, h - 60);
    const cols = ['#14b8a6', '#ffd23f', '#ff2f87', '#8b5cf6'];
    for (let i = 4; i > 0; i--) {
      ctx.beginPath();
      ctx.arc(w / 2, h / 2, i * 48, 0, TAU);
      ctx.strokeStyle = cols[i % cols.length];
      ctx.lineWidth = 9;
      ctx.stroke();
    }
    for (let a = 0; a < 24; a++) {
      const ang = (a / 24) * TAU;
      ctx.save();
      ctx.translate(w / 2 + Math.cos(ang) * 205, h / 2 + Math.sin(ang) * 205);
      ctx.rotate(ang);
      ctx.fillStyle = a % 2 ? '#14b8a6' : '#ffd23f';
      ctx.fillRect(-6, -6, 12, 12);
      ctx.restore();
    }
  });

  const staticTex = makeCanvasTexture(128, 96, (ctx, w, h) => {
    for (let y = 0; y < h; y += 3) {
      for (let x = 0; x < w; x += 3) {
        const v = 35 + Math.random() * 180;
        ctx.fillStyle = `rgb(${v * 0.7},${v * 0.85},${v})`;
        ctx.fillRect(x, y, 3, 3);
      }
    }
  });

  const familyTex = makeCanvasTexture(320, 240, (ctx, w, h) => {
    const grad = ctx.createLinearGradient(0, 0, 0, h);
    grad.addColorStop(0, '#78c8c2');
    grad.addColorStop(1, '#bd7b46');
    ctx.fillStyle = grad;
    ctx.fillRect(0, 0, w, h);
    ctx.fillStyle = '#f2c58d';
    ctx.fillRect(0, h * 0.72, w, h * 0.28);
    const people = [
      [58, 0.55, '#3d5d9c'],
      [118, 0.72, '#b64f63'],
      [176, 0.58, '#5c8a4f'],
      [238, 0.64, '#8f5fa5']
    ];
    people.forEach(([x, s, col], i) => {
      ctx.fillStyle = col;
      ctx.fillRect(x - 22 * s, 130 - 35 * s, 44 * s, 90 * s);
      ctx.fillStyle = i === 0 ? '#d9b48a' : '#e6b891';
      ctx.beginPath();
      ctx.arc(x, 108 - 28 * s, 17 * s, 0, TAU);
      ctx.fill();
      ctx.fillStyle = i === 2 ? '#3c2b1e' : '#5a3b26';
      ctx.beginPath();
      ctx.arc(x, 103 - 28 * s, 17 * s, Math.PI, TAU);
      ctx.fill();
    });
    ctx.fillStyle = '#fff4d6';
    ctx.font = 'bold 22px "Trebuchet MS", sans-serif';
    ctx.textAlign = 'center';
    ctx.fillText('THANKSGIVING ’94', w / 2, 28);
  });

  const neonTex = makeCanvasTexture(512, 256, (ctx, w, h) => {
    ctx.clearRect(0, 0, w, h);
    ctx.textAlign = 'center';
